#include <bits/stdc++.h>using namespace std;#define int long longint T,n;string s;void yz(){    cin >> n >> s;    s = '#' + s;    vector<bool> vis(n + 1,false);    int pos = 1,ans = 0;    for(int i=1;i<=n;i++){        vis[pos] = 1;        if(s[pos] == 'L'){            pos--;        }else{            pos++;        }    }    for(int i=1;i<=n;i++){        if(vis[i])ans++;    }    cout << ans << '\n';}signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)yz();    return 0;}